def ways(n):
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        dp[i] = dp[i - 1]
        if i >= 2:
            dp[i] += dp[i - 2]
    return dp[n]
print(ways(5))

calls = 0
memo = {0: 1, 1: 1}
def fact(n):
    global calls
    calls += 1
    if n in memo:
        return memo[n]
    memo[n] = n * fact(n - 1)
    return memo[n]
print(fact(4), fact(3), calls)

def lcs(a, b):
    dp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return dp[-1][-1]
print(lcs('abcde', 'ace'))

memo = {}
